// Mock of the LLM provider, the tuning parameters and the vision sidecar. A representative subset of the 72
// parameters (the real list is generated by the BE from env.ts / tuning-definitions); keys and defaults
// follow zalo-agent. Secrets never come back: only the masked tail of an API key.
import { bodyOf, fail, type Reply, type Router, type Schemas } from "../core";

type S = Schemas;
type TuningValue = S["TuningItem"]["value"];

const maskKey = (key: string): string => (key ? `••••${key.slice(-4)}` : "");

const provider = {
  provider: "openai-compatible" as S["LlmProviderKind"],
  base_url: "https://openrouter.ai/api/v1",
  model: "qwen3-8b",
  api_key: "",
};

function providerOut(): S["LlmSettingsOut"] {
  return {
    provider: provider.provider,
    base_url: provider.base_url,
    model: provider.model,
    api_key_masked: maskKey(provider.api_key),
    has_override: true,
  };
}

export const vision = {
  enabled: false,
  provider: "openai-compatible" as S["LlmProviderKind"] | null,
  base_url: "",
  model: "",
  api_key: "",
};

export function visionOut(): S["VisionSettingsOut"] {
  return {
    enabled: vision.enabled,
    provider: vision.provider,
    base_url: vision.base_url,
    model: vision.model,
    api_key_masked: maskKey(vision.api_key),
    has_override: Boolean(vision.base_url || vision.model),
  };
}

