const overrides = new Map<string, TuningValue>();

function tuningOut(): S["TuningOut"] {
  return {
    groups: GROUPS,
    items: DEFS.map((d) => ({
      ...d,
      value: overrides.get(d.key) ?? d.default,
      overridden: overrides.has(d.key),
    })),
  };
}

function validate(def: Def, value: TuningValue): string | null {
  if (def.kind === "number") {
    if (typeof value !== "number" || !Number.isFinite(value)) return `${def.label}: nhập một số.`;
    if (def.min != null && value < def.min) return `${def.label}: tối thiểu ${def.min}.`;
    if (def.max != null && value > def.max) return `${def.label}: tối đa ${def.max}.`;
  }
  if (def.kind === "select" && !def.options?.includes(String(value)))
    return `${def.label}: giá trị không hợp lệ.`;
  return null;
}

export function register(r: Router): void {
  r.get("/api/v1/admin/model/provider", "admin.model", (): Reply => ({ body: providerOut() }));

  r.patch("/api/v1/admin/model/provider", "admin.model", (ctx): Reply => {
    const input = bodyOf<S["LlmSettingsUpdate"]>(ctx);
    if (input.provider) provider.provider = input.provider;
    if (input.base_url !== undefined) provider.base_url = input.base_url ?? "";
    if (input.model !== undefined && input.model !== null) provider.model = input.model;
    if (input.api_key) provider.api_key = input.api_key;
    return { body: providerOut() };
  });

  r.delete("/api/v1/admin/model/provider", "admin.model", (): Reply => {
    Object.assign(provider, { base_url: "", model: "", api_key: "" });
    return { body: providerOut() };
  });

  r.post("/api/v1/admin/model/provider/test", "admin.model", (): Reply => {
    const body: S["LlmTestResult"] = provider.model
      ? { ok: true, reply: "Xin chào, tôi đã sẵn sàng." }
      : { ok: false, error: "Chưa cấu hình model." };
    return { body };
  });

  r.get("/api/v1/admin/model/tuning", "admin.model", (): Reply => ({ body: tuningOut() }));

  r.patch("/api/v1/admin/model/tuning", "admin.model", (ctx): Reply => {
    const { values } = bodyOf<S["TuningUpdate"]>(ctx);
    const entries = Object.entries(values);
    entries.forEach(([key, value]) => {
      const def = DEFS.find((d) => d.key === key);
      if (!def) fail(422, "validation_failed", `Tham số lạ: ${key}`);
      if (value === null) return;
      const problem = validate(def, value);
      if (problem) fail(422, "validation_failed", problem);
    });
    entries.forEach(([key, value]) => {
      if (value === null) overrides.delete(key);
      else overrides.set(key, value);
    });
    return { body: tuningOut() };
  });

  r.delete("/api/v1/admin/model/tuning", "admin.model", (): Reply => {
    overrides.clear();
    return { status: 204 };
  });

  r.get("/api/v1/admin/model/vision", "admin.model", (): Reply => ({ body: visionOut() }));

  r.patch("/api/v1/admin/model/vision", "admin.model", (ctx): Reply => {
    const input = bodyOf<S["VisionSettingsUpdate"]>(ctx);
    if (input.enabled !== undefined && input.enabled !== null) vision.enabled = input.enabled;
    if (input.provider) vision.provider = input.provider;
    if (input.base_url !== undefined) vision.base_url = input.base_url ?? "";
    if (input.model !== undefined) vision.model = input.model ?? "";
    if (input.api_key) vision.api_key = input.api_key;
    return { body: visionOut() };
  });

  r.delete("/api/v1/admin/model/vision/sidecar", "admin.model", (): Reply => {
    Object.assign(vision, { enabled: false, base_url: "", model: "", api_key: "" });
    return { status: 204 };
  });
}
